# Generated by build.py from recipe.yml for recipe http-check-logins-against-ldap. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p dir/.surl/ldap site
cat > dir/.surl/ldap/directory.ldif <<'EOF'
dn: dc=example,dc=com
objectClass: domain
dc: example

dn: ou=people,dc=example,dc=com
objectClass: organizationalUnit
ou: people

dn: uid=alice,ou=people,dc=example,dc=com
objectClass: inetOrgPerson
uid: alice
cn: Alice Liddell
sn: Liddell

dn: uid=bob,ou=people,dc=example,dc=com
objectClass: inetOrgPerson
uid: bob
cn: Bob Builder
sn: Builder
EOF
printf '%s\n' 'svcpass' > svc.pass
printf '%s\n' '6f1c0a9e3b7d4c2a8e5f1b0d9c7a3e6f' > control.token
cat > carol.ldif <<'EOF'
dn: uid=carol,ou=people,dc=example,dc=com
objectClass: inetOrgPerson
uid: carol
cn: Carol Danvers
sn: Danvers
EOF
printf '%s' '{"user":"carol","password":"marvel"}' > carol.json
printf '%s\n' 'q3 total: 1200' > site/report.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl -v --log-file web.log --directory site --cert server.pem --key server.key -u ops:opspass -u bob:localpass --user-ldap "ldap://127.0.0.1:8080/ou=people,dc=example,dc=com;bind-dn=cn=svc,dc=example,dc=com;bind-password-file=svc.pass;ca-file=server.pem" https://127.0.0.1:8081/ &
sleep 1
curl -sS --cacert server.pem -u alice:wonderland https://127.0.0.1:8081/report.txt
kill $(jobs -p)
